-- Seed ledger generated by scripts/build_seed.py. Do not edit by hand.
create or replace function pg_temp.seed_a(slug text, k text, num numeric, lo numeric, hi numeric, u text, txt text, src text, note text, conf text, by text, stale int)
returns void language sql as $$
  insert into assumptions (subject_type, subject_id, key, value_num, value_text, low, high, unit, currency, source_url, source_note, confidence, written_by, stale_after)
  select 'location', l.id, k, num, txt, lo, hi, u, case when u like '%usd%' then 'USD' end, src, note, conf::confidence_level, by, make_interval(days => stale)
  from locations l where l.slug = seed_a.slug
$$;
